"use client"

import { TooltipArrow, TooltipContent as TooltipContentPart } from "@ui-sdk/react/tooltip"

import { cn } from "@/lib/utils"

import type { TooltipContentProps } from "./tooltip.types"
import { tooltipArrowClasses, tooltipContentClasses } from "./tooltip.variants"

export function TooltipContent({ className, sideOffset = 6, arrow = true, children, ...props }: TooltipContentProps) {
  return (
    <TooltipContentPart sideOffset={sideOffset} className={cn(tooltipContentClasses, className)} {...props}>
      {children}
      {arrow && <TooltipArrow className={tooltipArrowClasses} />}
    </TooltipContentPart>
  )
}

"use client"

import { Tooltip as TooltipRoot } from "@ui-sdk/react/tooltip"

import type { TooltipProps } from "./tooltip.types"

export function Tooltip({ delay = 0, ...props }: TooltipProps) {
  return <TooltipRoot delay={delay} {...props} />
}

import type { ComponentProps, ReactNode } from "react"
import type { Tooltip as TooltipRoot, TooltipContent as TooltipContentPart } from "@ui-sdk/react/tooltip"

export type TooltipProps = ComponentProps<typeof TooltipRoot>

export type TooltipContentProps = Omit<ComponentProps<typeof TooltipContentPart>, "className" | "children"> & {
  className?: string
  children?: ReactNode
  /** Draws an arrow pointing at the trigger. Defaults to true. */
  arrow?: boolean
}
